import openpyxl
from collections import Counter, defaultdict
p='seed_collection_0003_inconsistent_color_4257_input.xlsx'
wb=openpyxl.load_workbook(p)

def color_key(c):
    if c is None: return ('None',)
    try:
        return (c.type, c.rgb, c.theme, c.indexed, c.tint)
    except Exception as e:
        return (c.type, 'ERR:'+str(e), c.theme, c.indexed, c.tint)

for ws in wb.worksheets:
    print('SHEET', ws.title)
    # Only cells with non-default fill: patternType not None OR fg rgb != 00000000 OR type theme/indexed
    interesting=[]
    for row in ws.iter_rows():
        for cell in row:
            f=cell.fill
            if f is None: continue
            c=f.fgColor; b=f.bgColor
            try:
                rgb=c.rgb if c is not None else None
            except Exception:
                rgb=None
            try:
                ctype=c.type if c is not None else None
            except Exception:
                ctype=None
            try:
                brgb=b.rgb if b is not None else None
            except Exception:
                brgb=None
            try:
                btype=b.type if b is not None else None
            except Exception:
                btype=None
            if f.patternType is not None or ctype != 'rgb' or (rgb not in (None,'00000000')) or btype != 'rgb' or (brgb not in (None,'00000000')):
                interesting.append((cell.coordinate, f.patternType, color_key(c), color_key(b), repr(cell.value)))
    print('interesting count', len(interesting))
    # group by pattern and colors
    groups=Counter((it[1], it[2], it[3]) for it in interesting)
    for g,n in groups.items():
        print('  GROUP', g, 'count', n)
    # print all interesting maybe limited
    for it in interesting[:200]:
        print('   ', it)
    print('---')
